theorem exists_unitLower_mul_upper_of_rowInclusion {A : Matrix n n ℝ}
    (hA : HasRowInclusion A) :
    ∃ H : Matrix n n ℝ, IsUnitLowerTriangular H ∧ (H * A).IsUpperTriangular

theorem _root_.Matrix.IsHermitian.isUnit_smul_one_sub_of_im_ne_zero {A : Matrix n n ℂ}
    (hA : A.IsHermitian) {ζ : ℂ} (hζ : ζ.im ≠ 0) :
    IsUnit (ζ • (1 : Matrix n n ℂ)-A)

theorem _root_.Matrix.IsHermitian.specNorm_resolvent_le {A : Matrix n n ℂ}
    (hA : A.IsHermitian) {ζ : ℂ} (hζ : ζ.im ≠ 0) :
    NLAlib.specNorm (resolvent A ζ) ≤ |ζ.im|⁻¹

theorem IsDiagonalizable.finrank_eigenspace_eq_rootMultiplicity {A : Matrix n n K}
    (hA : IsDiagonalizable A) (μ : K) :
    Module.finrank K (Module.End.eigenspace A.toLin' μ) = A.charpoly.rootMultiplicity μ

theorem mem_spectrum_of_diagonal_intertwining {A V : Matrix n n ℂ} {d : n → ℂ}
    (hV : IsUnit V) (hA : A * V = V * Matrix.diagonal d) (i : n) :
    d i ∈ spectrum ℂ A

theorem abs_trace_pow_le_trace_cfc_abs_pow {A : Matrix ι ι ℝ}
    (hA : A.IsHermitian) (k : ℕ) :
    |(A ^ k).trace| ≤ (cfc (fun x : ℝ => |x| ^ k) A).trace

theorem matrixLogarithmicNorm_le_of_energy_bound {A : Matrix n n ℂ} {c : ℝ}
    (hA : ∀ x : EuclideanSpace ℂ n,
      inner ℝ x (A.toEuclideanLin x) ≤ c * ‖x‖ ^ 2) : matrixLogarithmicNorm A ≤ c

theorem _root_.Matrix.PosDef.sub_smul_one_posDef_of_eigenvalues_gt {A : Matrix n n ℝ}
    (hA : A.PosDef) {δ : ℝ} (hδlt : ∀ i, δ < hA.isHermitian.eigenvalues i) :
    (A - δ • (1 : Matrix n n ℝ)).PosDef

theorem matrixGeometricMean_mul_inv_mul {A B : Matrix n n 𝕜}
    (hA : A.PosDef) (hB : B.PosSemidef) :
    matrixGeometricMean A B * A⁻¹ * matrixGeometricMean A B = B

theorem concaveOn_cfc_rpow {r : ℝ} (hr : r ∈ Set.Icc 0 1) :
    ConcaveOn ℝ {A : Matrix n n ℝ | A.PosSemidef}
      (fun A => cfc (fun x : ℝ => x ^ r) A)

theorem posSemidef_fromBlocks_matrixGeometricMean {A B : Matrix n n 𝕜}
    (hA : A.PosDef) (hB : B.PosSemidef) :
    (Matrix.fromBlocks A (matrixGeometricMean A B) (matrixGeometricMean A B) B).PosSemidef

theorem inverseSchulzIterate_sub_inv {A X : Matrix n n ℂ}
    (hA : IsUnit A) (k : ℕ) :
    inverseSchulzIterate A X k - A⁻¹ = -A⁻¹ * (1 - A * X) ^ (2 ^ k)

theorem tendsto_inverseSchulzIterate_inv {A X : Matrix n n ℂ}
    (h : spectralRadius ℂ (1 - A * X) < 1) :
    Tendsto (inverseSchulzIterate A X) atTop (𝓝 A⁻¹)

theorem OperatorMonotoneOn.cfc_le {I : Set ℝ} {f : ℝ → ℝ}
    (hf : OperatorMonotoneOn I f) {A B : Matrix n n ℂ}
    (hA : A.IsHermitian) (hB : B.IsHermitian)
    (hAI : spectrum ℝ A ⊆ I) (hBI : spectrum ℝ B ⊆ I) (hAB : A ≤ B) :
    cfc f A ≤ cfc f B

theorem spectrum_subset_of_order_interval [Nonempty n] {I : Set ℝ}
    (hI : Convex ℝ I) {A B C : Matrix n n ℂ}
    (hA : A.IsHermitian) (hB : B.IsHermitian) (hC : C.IsHermitian)
    (hAI : spectrum ℝ A ⊆ I) (hBI : spectrum ℝ B ⊆ I)
    (hAC : A ≤ C) (hCB : C ≤ B) : spectrum ℝ C ⊆ I

theorem OperatorMonotoneOn.posSemidef_loewnerMatrix {I : Set ℝ} {f : ℝ → ℝ}
    (hm : OperatorMonotoneOn I f) (hI : IsOpen I) (hf : DifferentiableOn ℝ f I)
    (ev : n → ℝ) (hev : ∀ i, ev i ∈ I) : (loewnerMatrix f ev).PosSemidef

theorem card_eigenvalues_lt_eq_card_neg_of_eq_mul_diagonal_mul {A : Matrix n n ℝ}
    (hA : A.IsHermitian) {x : ℝ} {L : Matrix n n ℝ} (hL : IsUnit L) {d : n → ℝ}
    (h : A - x • (1 : Matrix n n ℝ) = L * diagonal d * Lᵀ) :
    (Finset.univ.filter fun i => hA.eigenvalues i < x).card =
      (Finset.univ.filter fun i => d i < 0).card

theorem equivalent_toQuadraticForm'_transpose_mul_mul (A : Matrix n n ℝ) {X : Matrix n n ℝ}
    (hX : IsUnit X) :
    QuadraticMap.Equivalent (Xᵀ * A * X).toQuadraticForm' A.toQuadraticForm'

theorem inertia_diagonal_eq_of_congruence {B S : Matrix n n ℝ} {d : n → ℝ}
    (hS : IsUnit S) (hB : B = S * diagonal d * Sᵀ) :
    inertiaPos (diagonal d) = inertiaPos B ∧ inertiaNeg (diagonal d) = inertiaNeg B

theorem smul_add_smul_eq_congruence_diagonal {A B S : Matrix n n ℝ} {d : n → ℝ}
    (hA : A = S * Sᵀ) (hB : B = S * diagonal d * Sᵀ) (a b : ℝ) :
    a • A + b • B = S * diagonal (fun i => a + b * d i) * Sᵀ

theorem OperatorMonotoneOn.concaveOn_nonneg {f : ℝ → ℝ}
    (hm : OperatorMonotoneOn (Ici 0) f) (hf : ContinuousOn f (Ici 0)) :
    ConcaveOn ℝ (Ici 0) f

theorem _root_.ConcaveOn.apply_add_le_of_nonneg {f : ℝ → ℝ}
    (hf : ConcaveOn ℝ (Ici 0) f) (hf0 : f 0 = 0)
    {x y : ℝ} (hx : 0 ≤ x) (hy : 0 ≤ y) : f (x+y) ≤ f x + f y

theorem operatorCapacity_eq_sInf_ratio (hN : 0 < Fintype.card n)
    (T : Matrix n n ℂ →ₗ[ℝ] Matrix n n ℂ) :
    operatorCapacity T = sInf {d : ℝ | ∃ X : Matrix n n ℂ, X.PosDef ∧ d = (T X).det.re / X.det.re}
